AND business_date BETWEEN #{p.startDate} AND #{p.endDate}
AND entry_type=#{p.entryType}
AND entry_type IN ('EXPENSE','ADJUSTMENT')
AND funding_channel_id=#{p.fundingId}
AND primary_category_id=#{p.primaryCategoryId}
AND secondary_category_id=#{p.secondaryCategoryId}
AND product_id=#{p.productId}
AND purchase_channel_id=#{p.purchaseChannelId}
AND location_label_id=#{p.locationLabelId}
AND income_category_id=#{p.incomeCategoryId}
AND payer_id=#{p.payerId}
AND income_name=#{p.incomeName}
AND search_text ILIKE #{p.keyword} ESCAPE '\'
